def maxTurbulenceSize(arr):
    if not arr:
        return 0
    n = len(arr)
    max_len = 1
    up = down = 1   # up: last comparison arr[i-1] < arr[i]; down: arr[i-1] > arr[i]

    for i in range(1, n):
        if arr[i] > arr[i-1]:
            up = down + 1
            down = 1
        elif arr[i] < arr[i-1]:
            down = up + 1
            up = 1
        else:
            up = down = 1
        max_len = max(max_len, max(up, down))
    return max_len
